import { useState } from "react";
import axios from "axios";

export default function Chatbot() {
  const [message, setMessage] = useState("");
  const [chat, setChat] = useState([]);

  const sendMessage = async () => {
    if (!message) return;

    const userMsg = { type: "user", text: message };
    setChat(prev => [...prev, userMsg]);

    const res = await axios.post("/api/ai/chat", { message });

    const botMsg = { type: "bot", text: res.data.reply };
    setChat(prev => [...prev, botMsg]);

    setMessage("");
  };

  return (
    <div className="p-6">
      <h1 className="text-xl mb-4">AI Learning Assistant</h1>

      <div className="h-64 overflow-y-auto border p-3 mb-4 bg-white">
        {chat.map((msg, i) => (
          <div key={i} className={msg.type === "user" ? "text-right" : "text-left"}>
            <p className="mb-2">{msg.text}</p>
          </div>
        ))}
      </div>

      <div className="flex gap-2">
        <input
          className="border p-2 flex-1"
          value={message}
          onChange={(e) => setMessage(e.target.value)}
          placeholder="Ask something..."
        />
        <button onClick={sendMessage} className="bg-blue-500 text-white px-4">
          Send
        </button>
      </div>
    </div>
  );
}
